//! Inspect a tool invocation, its arguments and its result.
use crate::primitives::{
    brand_mark::brand_mark,
    clipboard,
    family::{Paint, disabled_motion},
    glyph::{Glyph, icon, spinner},
    ops_surface::*,
};
use gpui::{prelude::*, *};
use web_time::Instant;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ToolState {
    Running,
    Approval,
    Done,
    Failed,
    Denied,
}

pub struct Invocation {
    pub name: String,
    pub action: String,
    pub input: String,
    pub output: String,
    pub state: ToolState,
}

pub enum ToolAction {
    Approve(usize),
    Deny(usize),
    Retry(usize),
}

pub struct InvocationInspector {
    id: SharedString,
    pub calls: Vec<Invocation>,
    durations: Vec<SharedString>,
    group_open: bool,
    group_epoch: usize,
    compact: Option<bool>,
    open: Option<usize>,
    copied: Option<(usize, bool)>,
    visibility: fn() -> bool,
    clock: Instant,
}
impl EventEmitter<ToolAction> for InvocationInspector {}

impl InvocationInspector {
    pub fn new(id: impl Into<SharedString>, calls: Vec<Invocation>) -> Self {
        Self {
            id: id.into(),
            calls,
            durations: Vec::new(),
            group_open: true,
            group_epoch: 0,
            compact: None,
            open: None,
            copied: None,
            visibility: || true,
            clock: Instant::now(),
        }
    }

    /// Adds duration labels in call order.
    pub fn durations(mut self, durations: Vec<SharedString>) -> Self {
        self.durations = durations;
        self
    }

    /// Connects the visibility of an embedded preview to the running indicator.
    pub fn visibility(mut self, visible: fn() -> bool) -> Self {
        self.visibility = visible;
        self
    }

    fn request(&mut self, i: usize, action: ToolAction, cx: &mut Context<Self>) {
        let Some(call) = self.calls.get_mut(i) else {
            return;
        };
        match action {
            ToolAction::Approve(_) | ToolAction::Deny(_) if call.state != ToolState::Approval => {
                return;
            }
            ToolAction::Retry(_) if call.state != ToolState::Failed => return,
            _ => {}
        }
        call.state = if matches!(action, ToolAction::Deny(_)) {
            ToolState::Denied
        } else {
            ToolState::Running
        };
        cx.emit(action);
        cx.notify();
    }

    fn copy_input(&mut self, i: usize, cx: &mut Context<Self>) {
        let Some(call) = self.calls.get(i) else {
            return;
        };
        let request = clipboard::write(&call.input, cx);
        cx.spawn(async move |weak, cx| {
            let ok = request.await;
            let _ = weak.update(cx, |s, cx| {
                s.copied = Some((i, ok));
                cx.notify();
            });
        })
        .detach();
    }
}

fn tool_mark(name: &str, side: f32, cx: &App) -> AnyElement {
    brand_mark(name, side, cx)
        .unwrap_or_else(|| icon(Glyph::Settings, side, Paint::get(cx).secondary).into_any_element())
}

impl Render for InvocationInspector {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        let compact = self.compact.unwrap_or(w.viewport_size().width < px(470.));
        let weak = cx.weak_entity();
        let running = self
            .calls
            .iter()
            .filter(|call| call.state == ToolState::Running)
            .count();
        let failed = self
            .calls
            .iter()
            .filter(|call| call.state == ToolState::Failed)
            .count();
        let count = self.calls.len();
        let group_name = if count == 1 {
            if running > 0 {
                tr(cx, "Using 1 tool", "正在使用 1 个工具").to_owned()
            } else {
                tr(cx, "Used 1 tool", "使用了 1 个工具").to_owned()
            }
        } else if running > 0 {
            format!(
                "{} {count} {}",
                tr(cx, "Using", "正在使用"),
                tr(cx, "tools", "个工具")
            )
        } else {
            format!(
                "{} {count} {}",
                tr(cx, "Used", "使用了"),
                tr(cx, "tools", "个工具")
            )
        };
        let motion = !disabled_motion(cx) && (self.visibility)() && w.is_visible();
        let turn = if running > 0 && motion {
            w.request_animation_frame();
            self.clock.elapsed().as_secs_f32() * 1.15
        } else {
            0.
        };
        let mut marks = row().gap(px(2.)).flex_none();
        let mut seen = Vec::new();
        for call in &self.calls {
            if seen.contains(&call.name.as_str()) {
                continue;
            }
            seen.push(&call.name);
            marks = marks.child(
                div()
                    .size(px(20.))
                    .flex()
                    .items_center()
                    .justify_center()
                    .rounded_full()
                    .bg(p.panel)
                    .border_1()
                    .border_color(p.line)
                    .child(tool_mark(&call.name, 12., cx)),
            );
            if seen.len() == 3 {
                break;
            }
        }

        let head = item(
            "tools",
            tr(cx, "Tool calls", "工具调用"),
            cx,
            |s, _, cx| {
                s.group_open = !s.group_open;
                if s.group_open {
                    s.group_epoch = s.group_epoch.wrapping_add(1);
                }
                cx.notify();
            },
        )
        .w_full()
        .h(px(45.))
        .px(px(14.))
        .py_0()
        .gap_2()
        .border_1()
        .border_color(transparent_black())
        .aria_expanded(self.group_open)
        .child(marks)
        .child(
            swap_label("tools-used", group_name, w, cx)
                .flex_1()
                .min_w_0()
                .truncate()
                .text_size(px(13.)),
        )
        .when(failed > 0, |v| {
            v.child(
                note(format!("{failed} {}", tr(cx, "failed", "项失败")), cx).text_color(p.danger),
            )
        })
        .child(icon(
            if self.group_open {
                Glyph::Up
            } else {
                Glyph::Down
            },
            13.,
            p.secondary,
        ));
        let mut root = panel(&self.id, 560., cx).p_0().gap_0().child(
            div()
                .on_children_prepainted(move |bounds, _, cx| {
                    if let Some(head) = bounds.first() {
                        let narrow = head.size.width + px(2.) < px(440.);
                        if narrow != compact {
                            let _ = weak.update(cx, |s, cx| {
                                s.compact = Some(narrow);
                                cx.notify();
                            });
                        }
                    }
                })
                .child(head),
        );
        let group = Fold::get("tool-rows-fold", self.group_open, 125., 0.26, w, cx);
        if !group.mounted() {
            return root;
        }
        let mut rows = column().gap_0().border_t_1().border_color(p.line).p_1();
        for (i, c) in self.calls.iter().enumerate() {
            let (state, glyph, ink) = match c.state {
                ToolState::Running => (tr(cx, "Running", "运行中"), Glyph::Clock, p.secondary),
                ToolState::Approval => (
                    tr(cx, "Approval required", "等待批准"),
                    Glyph::Lock,
                    p.secondary,
                ),
                ToolState::Done => (tr(cx, "Done", "完成"), Glyph::Check, p.success),
                ToolState::Failed => (tr(cx, "Failed", "失败"), Glyph::Alert, p.danger),
                ToolState::Denied => (tr(cx, "Denied", "已拒绝"), Glyph::Close, p.secondary),
            };
            let open = self.open == Some(i);
            let duration = self.durations.get(i).map_or("", SharedString::as_ref);
            let meta = if c.state == ToolState::Done && !compact && !c.output.is_empty() {
                if duration.is_empty() {
                    c.output.clone()
                } else {
                    format!("{} · {duration}", c.output)
                }
            } else if !duration.is_empty() && c.state == ToolState::Done {
                duration.to_owned()
            } else {
                String::new()
            };
            let status = if c.state == ToolState::Running {
                spinner(turn, 14., ink).into_any_element()
            } else {
                icon(glyph, 14., ink).into_any_element()
            };
            let mut action_label = swap_label(("call-action", i), c.action.clone(), w, cx)
                .debug_selector(move || format!("tool-title-{i}"))
                .flex_1()
                .min_w_0()
                .truncate()
                .text_size(px(13.));
            if c.state == ToolState::Running {
                action_label =
                    action_label.text_color(p.ink.blend(p.secondary.opacity(if motion {
                        0.26 + (turn * std::f32::consts::TAU).sin() * 0.18
                    } else {
                        0.32
                    })));
            }
            let toggle = item(("call", i), c.action.clone(), cx, move |s, _, cx| {
                s.open = if s.open == Some(i) { None } else { Some(i) };
                s.copied = None;
                cx.notify();
            })
            .w_full()
            .h(px(40.))
            .py_0()
            .px(px(10.))
            .gap(px(9.))
            .aria_label(format!("{}: {} · {state}", c.name, c.action))
            .aria_expanded(open)
            .child(
                div()
                    .size(px(16.))
                    .flex_none()
                    .debug_selector(move || format!("tool-name-{i}"))
                    .child(tool_mark(&c.name, 16., cx)),
            )
            .child(action_label)
            .when(!meta.is_empty(), |v| {
                v.child(note(meta, cx).max_w(px(106.)).truncate())
            })
            .child(status)
            .child(icon(
                if open { Glyph::Up } else { Glyph::Down },
                12.,
                p.secondary,
            ));
            let mut section = column().gap_0().child(toggle);
            if matches!(
                c.state,
                ToolState::Approval | ToolState::Failed | ToolState::Denied
            ) {
                let reason = if c.output.is_empty() {
                    state.to_owned()
                } else {
                    c.output.clone()
                };
                let mut actions = row().gap(px(6.));
                if c.state == ToolState::Approval {
                    actions = actions
                        .child(
                            btn(
                                ("deny", i),
                                tr(cx, "Deny", "拒绝"),
                                false,
                                cx,
                                move |s, _, cx| s.request(i, ToolAction::Deny(i), cx),
                            )
                            .aria_label(format!("{}: {}", tr(cx, "Deny", "拒绝"), c.action))
                            .border_1()
                            .border_color(p.line),
                        )
                        .child(
                            btn(
                                ("allow", i),
                                tr(cx, "Allow", "批准"),
                                true,
                                cx,
                                move |s, _, cx| s.request(i, ToolAction::Approve(i), cx),
                            )
                            .aria_label(format!(
                                "{}: {}",
                                tr(cx, "Allow", "批准"),
                                c.action
                            )),
                        );
                } else if c.state == ToolState::Failed {
                    actions = actions.child(
                        btn(
                            ("retry", i),
                            tr(cx, "Retry", "重试"),
                            false,
                            cx,
                            move |s, _, cx| s.request(i, ToolAction::Retry(i), cx),
                        )
                        .aria_label(format!("{}: {}", tr(cx, "Retry", "重试"), c.action))
                        .border_1()
                        .border_color(p.line),
                    );
                }
                section = section.child(
                    row()
                        .when(compact, |v| v.flex_col().items_start())
                        .px(px(10.))
                        .pl(px(35.))
                        .pb_2()
                        .child(
                            note(reason, cx)
                                .flex_1()
                                .debug_selector(move || format!("tool-reason-{i}")),
                        )
                        .child(actions),
                );
            }
            let detail = Fold::get(("tool-detail", i), open, 125., 0.26, w, cx);
            if detail.mounted() {
                let copy_label = match self.copied {
                    Some((selected, true)) if selected == i => tr(cx, "Copied", "已复制"),
                    Some((selected, false)) if selected == i => tr(cx, "Copy failed", "复制失败"),
                    _ => tr(cx, "Copy input", "复制输入"),
                };
                section = section.child(
                    detail.wrap(
                        0.,
                        column()
                            .pl(px(if compact { 10. } else { 35. }))
                            .pr(px(10.))
                            .pb_3()
                            .child(
                                row()
                                    .justify_between()
                                    .child(title(tr(cx, "Input", "输入")))
                                    .child(btn(
                                        ("copy-tool-input", i),
                                        copy_label,
                                        false,
                                        cx,
                                        move |s, _, cx| s.copy_input(i, cx),
                                    )),
                            )
                            .child(
                                div()
                                    .id(("tool-input-code", i))
                                    .px_2()
                                    .py_2()
                                    .rounded(crate::foundation::surface_radius(cx))
                                    .bg(p.stage)
                                    .overflow_x_scroll()
                                    .whitespace_nowrap()
                                    .child(note(c.input.clone(), cx)),
                            )
                            .child(title(tr(cx, "Output", "输出")))
                            .child(note(
                                if c.output.is_empty() {
                                    "—".to_owned()
                                } else {
                                    c.output.clone()
                                },
                                cx,
                            )),
                    ),
                );
            }
            rows = rows.child(arrive(
                section,
                (
                    "tool-row",
                    self.group_epoch.wrapping_mul(131).wrapping_add(i),
                ),
                (i.min(12) * 20) as u64,
                6.,
                cx,
            ));
        }
        root = root.child(group.wrap(0., rows));
        root
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Editable Unicode text, IME composition and selection shared by KUI fields.
use crate::primitives::family::{Paint, disabled_motion, ease};
use gpui::{prelude::*, *};
use std::{ops::Range, time::Duration};
use unicode_segmentation::UnicodeSegmentation;
use web_time::Instant;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum InputMode {
    Single,
    Multi,
    Password,
    Search,
    Combobox,
    InlineMulti,
}
impl InputMode {
    fn multiline(self) -> bool {
        matches!(self, Self::Multi | Self::InlineMulti)
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EditEvent {
    Changed,
    Submitted,
    Escape,
    Navigate(bool),
    Focused,
    Blurred,
}
/// Optional inline completion events, separate from ordinary edit events.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EditorCompletionEvent {
    SelectionChanged,
    CompositionEnded,
    Accepted { text: SharedString, word: bool },
    Dismissed,
}
/// Opt-in editor shortcuts, independent of normal text and composition events.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EditorShortcutEvent {
    CommandSubmit,
}
fn is_command_submit(
    enabled: bool,
    composing: bool,
    key: &str,
    command: bool,
    shift: bool,
    alt: bool,
) -> bool {
    enabled && !composing && key == "enter" && command && !shift && !alt
}
struct Layout {
    bounds: Bounds<Pixels>,
    origin: Point<Pixels>,
    rows: Vec<WrappedLine>,
    line: Pixels,
    // Only populated when the painted text differs from the editable text.
    mask: Vec<usize>,
}
impl Layout {
    fn visible_index(&self, index: usize) -> usize {
        if self.mask.is_empty() {
            index
        } else {
            self.mask.partition_point(|p| *p < index) * '•'.len_utf8()
        }
    }
    fn index(&self, index: usize) -> usize {
        if self.mask.is_empty() {
            index
        } else {
            *self.mask.get(index / '•'.len_utf8()).unwrap_or_else(|| {
                self.mask
